import React, { Component } from 'react';
import ErrorBoundaryPropTypes from './ErrorBoundary.propTypes';

class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError() {
    return { hasError: true }; //display fallback on next render
  }

  componentDidCatch(error, errorInfo) {
    console.error('ErrorBoundary caught an error', error, errorInfo); // eslint-disable-line
  }

  render() {
    const { hasError } = this.state;
    const { fallback, children } = this.props;
    const handleOnClick = () => {
      window.location.reload();
    };

    if (hasError) {
      return (
        fallback || (
          <div className='fallback__container'>
            <h2 className='fallback__container-title'>Something went wrong.</h2>
            <button onClick={handleOnClick} className='fallback__container-button'>
              Reload Page
            </button>
          </div>
        )
      );
    }

    return children;
  }
}

ErrorBoundary.propTypes = ErrorBoundaryPropTypes;

export default ErrorBoundary;

