```tsx
const renderQuestionComponent = (
  type: QuestionType | null | undefined,
  key: Key | null | undefined,
  choices?: (string | null | undefined)[],
  question?: string,
  id?: string,
  version?: number,
  topic?: string,
  showIf?: DependencyCondition[] | null | undefined[],
  showTopic?: boolean
) => {
  const questionRegex = /\b(?!version\b)([a-zA-Z_]+)-([a-fA-F0-9-]{36})\b/;

  // Function to check if the question should be shown
  const showQuestion = showIf?.every((conditions) =>
    conditions?.conditions?.some((condition) => {
      if (!condition) return false;

      // Find the answer that matches the dependent question ID
      const answerKey = Object.keys(formValues).find((key) => {
        const match = key.match(questionRegex);
        return match && match[0].includes(condition.dependent_question_id || '');
      });

      if (!answerKey) return false;

      const answerValue = formValues[answerKey as keyof typeof formValues];

      // Check conditions
      if (condition.equals_bool !== undefined) {
        return (answerValue === 'true' || answerValue === true) === condition.equals_bool;
      }
      if (condition.equals_choice?.length) {
        return condition.equals_choice.includes(answerValue as string);
      }
      if (!isNil(condition.greater_than)) {
        return (answerValue as number) > condition.greater_than;
      }
      if (!isNil(condition.less_than)) {
        return (answerValue as number) < condition.less_than;
      }

      return false;
    })
  );

  if (!isNil(showQuestion) && !showQuestion) return null;

  // Reusable Question Header Component
  const QuestionHeader = () => (
    <Box pb={2} pt={!isMobile ? 4 : 0}>
      {showTopic && (
        <TitleBox>
          <Typography fontSize={20} fontWeight={700}>{topic}</Typography>
        </TitleBox>
      )}
      <Box mb={4}>
        <Typography>{question}</Typography>
      </Box>
    </Box>
  );

  // Reusable Hidden Fields
  const HiddenFields = () => (
    <>
      <Field name={id || ''} initialValue={id || ''}>{() => <></>}</Field>
      <Field name={`version-${id}`} initialValue={version || 0}>{() => <></>}</Field>
    </>
  );

  switch (type) {
    case QuestionType.Multiple:
      return (
        <Box pb={2} pt={!isMobile ? 4 : 0}>
          <QuestionHeader />
          <CheckboxFieldGroup name="multi">
            {choices?.map((choice, index) => (
              <Box
                key={index}
                border={`1px solid ${lighten(theme.colours.portalOptions.gray, 0.9)}`}
                paddingLeft={1}
                marginBottom={2}
                borderRadius={1}
              >
                <Field name={`multiple_choice_answer-${id}_${index}`} type="checkbox">
                  {({ input }) => <CheckboxField label={choice} disabled={loading} {...input} />}
                </Field>
              </Box>
            ))}
          </CheckboxFieldGroup>
          <HiddenFields />
        </Box>
      );

    case QuestionType.Freetext:
      return (
        <Box pb={2} pt={!isMobile ? 4 : 0}>
          <QuestionHeader />
          <TextFieldFF
            name={`free_text_answer-${id}`}
            multiline
            key={key}
            rows={8}
            sx={{ display: 'block', '& .MuiBox-root': { width: '30rem' } }}
          />
          <HiddenFields />
        </Box>
      );

    case QuestionType.ZeroTenScale:
    case QuestionType.TenScale:
    case QuestionType.FiveScale: {
      const scaleItems = type === QuestionType.ZeroTenScale ? 11 : type === QuestionType.TenScale ? 10 : 5;
      return (
        <>
          <Field name={`${type === QuestionType.ZeroTenScale ? 'zero_ten_scale' : type === QuestionType.TenScale ? 'ten_scale' : 'five_scale'}_answer-${id}`} type="radiogroup">
            {({ input }) => (
              <Box pb={2} pt={!isMobile ? 4 : 0}>
                <QuestionHeader />
                <Box mb={4}>
                  <ToggleButtonScale
                    items={scaleItems}
                    key={key}
                    {...input}
                    fullWidth
                    highEndLabel={type === QuestionType.FiveScale ? formatMessage('toggleButtonScale.agree') : undefined}
                    lowEndLabel={type === QuestionType.FiveScale ? formatMessage('toggleButtonScale.disagree') : undefined}
                  />
                </Box>
              </Box>
            )}
          </Field>
          <HiddenFields />
        </>
      );
    }

    case QuestionType.Single:
      return (
        <>
          <Field name={`single_choice_answer-${id}`} type="radiogroup">
            {({ input }) => (
              <RadioFieldGroup
                sx={{ gap: 1, width: '100%' }}
                label={<QuestionHeader />}
                {...input}
                variant="outlined"
                layout="column"
              >
                <Box width="100%" pb={1} sx={{ label: { marginBottom: '1rem' } }}>
                  {choices?.map((choice, index) => (
                    <RadioField key={index} variant="outlined" label={<Box>{choice}</Box>} value={choice} disabled={loading} />
                  ))}
                </Box>
              </RadioFieldGroup>
            )}
          </Field>
          <HiddenFields />
        </>
      );

    case QuestionType.Bool:
      return (
        <>
          <Field name={`bool_answer-${id}`} type="radiogroup">
            {({ input }) => (
              <RadioFieldGroup
                sx={{ gap: 1 }}
                label={<QuestionHeader />}
                {...input}
